#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Score replay runs: each run synced the same blocks from a local source node, starting from the same database copy.

Per run directory: node_timestats.log[.gz] (the node's time-stats lines, "Height: N coinbase ... p/t: T (13 fields)ms";
"Height: N" means block N-1 was added; times are UTC) and samples.csv[.gz] (unix_s, height, ticks: the node's
cumulative user+system CPU in 1/100 s, sampled about once a second).

Window: from the time block H0 was added to the time block H1 was added. CPU: the ticks interpolated linearly at
those two times. Also the median p/t and median t3 (fifth field) over blocks H0..H1.
A run's arm is the letter after the last underscore of its directory name (d9x1_B -> B).
Summary: each arm against the baseline as the ratio of medians, with an overlap check.

usage: replay_score.py <runs dir> <run>... [--h0 3103320] [--h1 3103500] [--base B]
"""
import argparse, csv, datetime, gzip, os, re, statistics, sys

def opn(path):
    if os.path.exists(path):
        return open(path, errors="replace")
    return gzip.open(path + ".gz", "rt", errors="replace")

ap = argparse.ArgumentParser()
ap.add_argument("dir"); ap.add_argument("runs", nargs="+")
ap.add_argument("--h0", type=int, default=3103320); ap.add_argument("--h1", type=int, default=3103500)
ap.add_argument("--base", default="B")
a = ap.parse_args()

res = {}
print("%-8s %4s %9s %9s %7s %9s %9s %7s" % ("run", "arm", "wall_s", "cpu_s", "cores", "p/t_med", "t3_med", "blocks"))
for run in a.runs:
    added, pt, t3 = {}, [], []
    for line in opn(os.path.join(a.dir, run, "node_timestats.log")):
        m = re.match(r"(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d\.\d+)\s.*Height: (\d+) coinbase.*p/t: (\d+) \(([\d/]+)\)ms", line)
        if not m:
            continue
        h = int(m.group(2)) - 1
        added[h] = datetime.datetime.strptime(m.group(1), "%Y-%m-%d %H:%M:%S.%f").replace(tzinfo=datetime.timezone.utc).timestamp()
        if a.h0 <= h <= a.h1:
            pt.append(int(m.group(3))); t3.append(int(m.group(4).split("/")[4]))
    if a.h0 not in added or a.h1 not in added:
        sys.exit("%s: the window is not complete in the log" % run)
    ta, tb = added[a.h0], added[a.h1]
    rows = [(float(r["unix_s"]), int(r["ticks"])) for r in csv.DictReader(opn(os.path.join(a.dir, run, "samples.csv"))) if r["ticks"]]
    def ticks(t):
        for (t1, k1), (t2, k2) in zip(rows, rows[1:]):
            if t1 <= t <= t2:
                return k1 + (k2 - k1) * (t - t1) / (t2 - t1) if t2 > t1 else k1
        sys.exit("%s: no CPU samples around %.1f" % (run, t))
    wall, cpu = tb - ta, (ticks(tb) - ticks(ta)) / 100.0
    arm = run.rsplit("_", 1)[-1]
    res.setdefault(arm, []).append((wall, cpu))
    print("%-8s %4s %9.1f %9.1f %7.2f %9.0f %9.0f %7d" % (run, arm, wall, cpu, cpu / wall, statistics.median(pt), statistics.median(t3), len(pt)))
if a.base not in res:
    sys.exit("no runs of the baseline arm %s" % a.base)
bw = [x[0] for x in res[a.base]]; bc = [x[1] for x in res[a.base]]
for arm in sorted(res):
    if arm == a.base:
        continue
    w = [x[0] for x in res[arm]]; c = [x[1] for x in res[arm]]
    rw, rc = statistics.median(w) / statistics.median(bw), statistics.median(c) / statistics.median(bc)
    print("%s/%s: wall %.3f (%+.1f%%; %s against %s, %s); CPU %.3f (%+.1f%%; %s against %s)" % (
        arm, a.base, rw, 100 * (rw - 1), " ".join("%.1f" % x for x in w), " ".join("%.1f" % x for x in bw),
        "no overlap" if max(w) < min(bw) or min(w) > max(bw) else "overlap",
        rc, 100 * (rc - 1), " ".join("%.1f" % x for x in c), " ".join("%.1f" % x for x in bc)))
